#!/usr/bin/perl
use strict; use warnings;
my %UNC = map { $_ => 1 } qw(equipment information rice money species series fish sheep jeans police);
my @RULES = (
  [qr/analyses$/,    sub { "analyasis" } ],
  [qr/bases$/,       sub { "basis" } ],
  [qr/diagnoses$/,   sub { "diagnosis" } ],
  [qr/parentheses$/, sub { "parenthesis" } ],
  [qr/prognoses$/,   sub { "prognosis" } ],
  [qr/synopses$/,    sub { "synopsis" } ],
  [qr/theses$/,      sub { "thesis" } ],
  [qr/crises$/,      sub { "crisis" } ],
  [qr/testes$/,      sub { "testis" } ],
  [qr/axes$/,        sub { "axis" } ],
  [qr/buses$/,       sub { "bus" } ],
  [qr/aliases$/,     sub { "alias" } ],
  [qr/statuses$/,    sub { "status" } ],
  [qr/quizzes$/,     sub { "quiz" } ],
  [qr/news$/,        sub { "news" } ],
);
sub singularize {
  my ($s) = @_;
  return $s if $UNC{$s};
  for my $r (@RULES) {
    my ($re, $rep) = @$r;
    if ($s =~ /$re/) { my $pre = substr($s, 0, $-[0]); return $pre . $rep->(); }
  }
  if ($s =~ /([^f])ves$/)          { return substr($s,0,$-[0]) . $1 . "fe"; }
  if ($s =~ /([^aeiouy]|qu)ies$/)  { return substr($s,0,$-[0]) . $1 . "y"; }
  if ($s =~ /(x|ch|ss|sh)es$/)     { return substr($s,0,$-[0]) . $1; }
  if ($s =~ /(o)es$/)              { return substr($s,0,$-[0]) . $1; }
  if ($s =~ /s$/)                  { return substr($s,0,length($s)-1); }
  return $s;
}
while (my $w = <STDIN>) { chomp $w; print singularize($w . "s"), "\n"; }
PERL
