cat > full.pl <<'PERL'
#!/usr/bin/perl
use strict; use warnings;
sub up { my $s=shift; $s =~ tr/a-z/A-Z/; $s }
sub dn { my $s=shift; $s =~ tr/A-Z/a-z/; $s }
sub ucf { my $s=shift; return $s if $s eq ''; substr($s,0,1) = up(substr($s,0,1)); $s }
sub lcf { my $s=shift; return $s if $s eq ''; substr($s,0,1) = dn(substr($s,0,1)); $s }
my %UNC = map { $_ => 1 } qw(equipment information rice money species series fish sheep jeans police);
my @SPEC = ( ['analyses','analyasis'], ['bases','basis'], ['diagnoses','diagnosis'],
  ['parentheses','parenthesis'], ['prognoses','prognosis'], ['synopses','synopsis'],
  ['theses','thesis'], ['crises','crisis'], ['testes','testis'], ['axes','axis'],
  ['buses','bus'], ['aliases','alias'], ['statuses','status'], ['quizzes','quiz'], ['news','news'] );
sub pluralize { my $w=shift; $UNC{$w} ? $w : $w."s" }
sub singularize {
  my ($s)=@_;
  return $s if $UNC{$s};
  for my $r (@SPEC) {
    my ($suf,$rep)=@$r;
    if (length($s) >= length($suf) && substr($s,-length($suf)) eq $suf) {
      return substr($s,0,length($s)-length($suf)) . $rep;
    }
  }
  if ($s =~ /([^f])ves$/)         { return substr($s,0,$-[0]) . $1 . "fe" }
  if ($s =~ /([^aeiouy]|qu)ies$/) { return substr($s,0,$-[0]) . $1 . "y" }
  if ($s =~ /(x|ch|ss|sh)es$/)    { return substr($s,0,$-[0]) . $1 }
  if ($s =~ /(o)es$/)             { return substr($s,0,$-[0]) . $1 }
  if ($s =~ /s$/)                 { return substr($s,0,length($s)-1) }
  return $s;
}
sub camelize {
  my ($s,$upper)=@_; my $out=''; my $first=1;
  for my $seg (split /_/, $s, -1) {
    next if $seg eq '';
    if ($first) { $out .= $upper ? ucf($seg) : lcf($seg); $first=0 } else { $out .= ucf($seg) }
  }
  $out;
}
sub underscore {
  my ($s)=@_; my $out='';
  for my $i (0..length($s)-1) {
    my $c = substr($s,$i,1);
    if ($c ge 'A' && $c le 'Z') { $out .= '_' if $i>0; $out .= dn($c) } else { $out .= $c }
  }
  $out;
}
sub classify { camelize(singularize($_[0]), 1) }
sub tableize { pluralize(underscore($_[0])) }
sub humanize { my $s=shift; $s =~ s/_/ /g; ucf($s) }
sub titleize {
  my $s = dn($_[0]); my $out='';
  for my $i (0..length($s)-1) {
    my $c = substr($s,$i,1);
    $out .= ($i==0 || substr($s,$i-1,1) eq ' ') ? up($c) : $c;
  }
  $out;
}
sub dasherize { my $s=shift; $s =~ s/_/-/g; $s }
sub parameterize {
  my ($s,$sep)=@_; $sep='-' unless defined $sep; my $out='';
  for my $i (0..length($s)-1) {
    my $c = substr($s,$i,1);
    if ($c =~ /^[A-Za-z0-9]$/) { $out .= dn($c) } elsif ($c eq ' ') { $out .= $sep }
  }
  $out;
}
sub capitalize { ucf(dn($_[0])) }
my $w = $ARGV[0];
print pluralize($w),"\n", singularize($w."s"),"\n", camelize("test_".$w),"\n",
      underscore("Test".$w),"\n", classify($w."_table"),"\n", tableize($w."Class"),"\n",
      humanize($w."_id"),"\n", titleize($w),"\n", dasherize($w),"\n",
      parameterize("The ".$w." Test"),"\n", up($w),"\n", dn($w),"\n", capitalize($w),"\n";
PERL
# smoke check vs documented examples
for w in cat dog person child mouse; do
  if diff <(/workspace/dataset/test13_executable "$w") <(perl full.pl "$w") >/dev/null; then echo "OK  $w"; else echo "FAIL $w"; diff <(/workspace/dataset/test13_executable "$w") <(perl full.pl "$w"); fi
done

cd /tmp/xcheck
# build a large, diverse corpus (NUL-safe: one arg per line, no newlines inside args)
perl -e '
my @a=("a".."z"); my @A=("A".."Z"); my @d=(0..9);
my @out;
push @out, "";
push @out, $_ for @a; push @out, $_ for @A; push @out, $_ for @d;
for my $x (@a){ for my $y (@a){ push @out,"$x$y" } }
for my $x (@a){ for my $y (@a){ for my $z (@a){ push @out,"$x$y$z" } } }
# every printable ASCII char alone and embedded
for my $c (32..126){ my $ch=chr($c); push @out,$ch; push @out,"a${ch}z"; push @out,"${ch}Foo"; push @out,"Foo${ch}"; }
# high bytes / UTF-8 / invalid utf8
for my $c (128..255){ my $ch=chr($c); push @out,"a${ch}z" }
push @out, ("caf\xc3\xa9","na\xc3\xafve","\xc3\x84\xc3\x96\xc3\x9c","\xc3\x9f","\xe6\x97\xa5\xe6\x9c\xac\xe8\xaa\x9e",
  "\xf0\x9f\x98\x80","\xff","\xc3","\x80","\xed\xa0\x80","e\xcc\x81");
# suffix families x prefixes
my @suf = qw(s ss es ies ves oes ses xes ches shes sses zes zzes uses ises ases oses eses is us as os ys y f fe o e
  analyses bases diagnoses parentheses prognoses synopses theses crises testes axes buses aliases statuses quizzes news
  analysis basis thesis crisis testis axis bus alias status quiz sis ves ives lves rves aves eves oves uves);
my @pre = ("","a","x","z","re","un","the","wax","ab","xy","qu","sh","ch","ss","o","i","hypo","dia","syn","par","pro","cri","test","al","st","bu","ne","an","xanaly","ana");
for my $p (@pre){ for my $s (@suf){ push @out, "$p$s" } }
# structural
push @out, ("_","__","___","_a","a_","_a_","a__b","a-b","a.b","a/b","a::b","::a","a:b","a b","a  b"," a","a ",
  "  ","\t","a\tb","FooBar","fooBar","foo_bar","FOO_BAR","HTTPServer","XMLHTTPRequest","aB","Ab","ABc","aBc",
  "A1b2C3","1a","a1","12","1_2","a1_b2","sCrAmBlEd","ALLCAPS","x"x100,"ab"x500,("z"x5000),
  "cat_table","catClass","test_cat","Testcat","The cat Test","-","--","-a","a-","+","=","%","\$","\@","!","?","*",
  "sheep","fish","money","information","series","species","equipment","rice","jeans","police",
  "Sheep","SHEEP","sheeps","fishs","polices","serie","specie","xseries","xspecies");
my %seen; my @u = grep { !$seen{$_}++ } @out;
print "$_\n" for @u;
' > corpus2.txt
wc -l < corpus2.txt

