//! Byte-level ASCII helpers.
//!
//! The C++ original operates on `std::string`, i.e. a sequence of bytes, and uses
//! the `<cctype>` functions under the default "C" locale. That means only the 52
//! ASCII letters are ever case-mapped: bytes `0x80..=0xFF` (and therefore every
//! byte of a multi-byte UTF-8 sequence) pass through untouched. Everything here
//! works on `u8` for exactly that reason -- using Rust's `char`-based
//! `to_uppercase`/`to_lowercase` would case-map non-ASCII text and diverge.

/// Uppercase a single byte, ASCII only.
pub fn to_upper(b: u8) -> u8 {
    if b.is_ascii_lowercase() {
        b - 32
    } else {
        b
    }
}

/// Lowercase a single byte, ASCII only.
pub fn to_lower(b: u8) -> u8 {
    if b.is_ascii_uppercase() {
        b + 32
    } else {
        b
    }
}

/// Uppercase every ASCII letter in `s`.
pub fn upcase(s: &[u8]) -> Vec<u8> {
    s.iter().map(|&b| to_upper(b)).collect()
}

/// Lowercase every ASCII letter in `s`.
pub fn downcase(s: &[u8]) -> Vec<u8> {
    s.iter().map(|&b| to_lower(b)).collect()
}

/// Uppercase only the first byte, leaving the remainder of `s` untouched.
///
/// Note this is deliberately *not* `capitalize`: it does not lowercase the tail.
/// `camelize` and `humanize` need this variant (e.g. `camelize("test_ABCdef")`
/// yields `testABCdef`, not `testAbcdef`).
pub fn upper_first(s: &[u8]) -> Vec<u8> {
    let mut out = s.to_vec();
    if let Some(first) = out.first_mut() {
        *first = to_upper(*first);
    }
    out
}

/// Lowercase only the first byte, leaving the remainder of `s` untouched.
pub fn lower_first(s: &[u8]) -> Vec<u8> {
    let mut out = s.to_vec();
    if let Some(first) = out.first_mut() {
        *first = to_lower(*first);
    }
    out
}

/// Replace every occurrence of `from` with `to`.
pub fn replace_byte(s: &[u8], from: u8, to: u8) -> Vec<u8> {
    s.iter()
        .map(|&b| if b == from { to } else { b })
        .collect()
}

/// Concatenate two byte strings, mirroring C++'s `std::string` `operator+`.
pub fn concat(a: &[u8], b: &[u8]) -> Vec<u8> {
    let mut out = Vec::with_capacity(a.len() + b.len());
    out.extend_from_slice(a);
    out.extend_from_slice(b);
    out
}

