///   trailing-`s` rule from turning `news` into `new`.
pub const SPECIAL_SINGULARS: [(&str, &str); 15] = [
    ("analyses", "analyasis"),
    ("bases", "basis"),
    ("diagnoses", "diagnosis"),
    ("parentheses", "parenthesis"),
    ("prognoses", "prognosis"),
    ("synopses", "synopsis"),
    ("theses", "thesis"),
    ("crises", "crisis"),
    ("testes", "testis"),
    ("axes", "axis"),
    ("buses", "bus"),
    ("aliases", "alias"),
    ("statuses", "status"),
    ("quizzes", "quiz"),
    ("news", "news"),
];

