        if n >= 3 && word.ends_with(b"oes") {
            return word[..n - 2].to_vec();
        }

        // s$ -> ''
        if word.ends_with(b"s") {
            return word[..n - 1].to_vec();
        }

        word.to_vec()
    }

    /// `camelize` with the reference implementation's default: the first segment
    /// keeps a lowercase initial, so `test_foo_bar` becomes `testFooBar`.
    pub fn camelize(term: &[u8]) -> Vec<u8> {
        Self::camelize_with(term, false)
    }

    /// Join `_`-separated segments, uppercasing each segment's first byte.
    ///
    /// `upper_first_letter` controls only the *first* segment, mirroring the
    /// C++ `camelize(const std::string&, bool)` overload.
    ///
    /// Only `_` separates: `-`, `.`, `/`, `::` and spaces are ordinary content,
    /// so `test_foo-bar` becomes `testFoo-bar`. Empty segments are skipped,
    /// which is why `test___x` collapses to `testX`. Only the leading byte of a
    /// segment changes case -- `test_ABCdef` stays `testABCdef`.
    pub fn camelize_with(term: &[u8], upper_first_letter: bool) -> Vec<u8> {
        let mut out = Vec::with_capacity(term.len());
        let mut is_first_segment = true;
        for segment in term.split(|&b| b == b'_') {
            if segment.is_empty() {
                continue;
            }
            let piece = if is_first_segment {
                is_first_segment = false;
                if upper_first_letter {
                    ascii::upper_first(segment)
                } else {
                    ascii::lower_first(segment)
                }
            } else {
                ascii::upper_first(segment)
            };
            out.extend_from_slice(&piece);
        }
        out
    }

    /// Insert `_` before every uppercase ASCII letter and lowercase it.
    ///
    /// The separator goes in ahead of *any* uppercase byte past position 0,
    /// regardless of what precedes it, so `Test_Foo` becomes `test__foo` and
    /// `Test-Foo` becomes `test-_foo`. There is no acronym grouping
    /// (`TestHTTPServer` -> `test_h_t_t_p_server`) and `::` is left alone
    /// (`Test::Foo` -> `test::_foo`).
    pub fn underscore(camel_cased_word: &[u8]) -> Vec<u8> {
        let mut out = Vec::with_capacity(camel_cased_word.len() * 2);
        for (i, &b) in camel_cased_word.iter().enumerate() {
            if b.is_ascii_uppercase() {
                if i > 0 {
                    out.push(b'_');
                }
                out.push(ascii::to_lower(b));
            } else {
                out.push(b);
            }
        }
        out
    }

    /// Singularize, then camelize with an uppercase initial:
    /// `cat_table` -> `CatTable`.
    ///
    /// Namespaces are *not* stripped, so `Foo.Bar_table` -> `Foo.BarTable`
    /// and `::Foo_table` -> `::FooTable`.
    pub fn classify(table_name: &[u8]) -> Vec<u8> {
        Self::camelize_with(&Self::singularize(table_name), true)
    }

    /// Underscore, then pluralize: `catClass` -> `cat_classs`.
    pub fn tableize(class_name: &[u8]) -> Vec<u8> {
        Self::pluralize(&Self::underscore(class_name))
    }

    /// Turn `_` into spaces and uppercase the first byte: `cat_id` -> `Cat id`.
    ///
    /// Nothing else changes -- the tail is not lowercased (`FooBar_id` ->
    /// `FooBar id`), no `underscore` pass is applied, and a trailing `_id` is
    /// not special (`cat_id` keeps its `id`).
    pub fn humanize(lower_case_and_underscored_word: &[u8]) -> Vec<u8> {
        let spaced = ascii::replace_byte(lower_case_and_underscored_word, b'_', b' ');
        ascii::upper_first(&spaced)
    }

    /// Lowercase everything, then uppercase the first byte of every
    /// space-delimited word: `foo bar` -> `Foo Bar`.
    ///
    /// A plain space (`0x20`) is the only word boundary. Tabs, newlines and `_`
    /// are not, so `a\tb` -> `A\tb` and `foo_bar` -> `Foo_bar`.
    pub fn titleize(word: &[u8]) -> Vec<u8> {
        let lowered = ascii::downcase(word);
        let mut out = Vec::with_capacity(lowered.len());
        for (i, &b) in lowered.iter().enumerate() {
            if i == 0 || lowered[i - 1] == b' ' {
                out.push(ascii::to_upper(b));
            } else {
                out.push(b);
            }
        }
        out
    }

    /// Replace `_` with `-`, changing nothing else.
    pub fn dasherize(underscored_word: &[u8]) -> Vec<u8> {
        ascii::replace_byte(underscored_word, b'_', b'-')
    }

    /// `parameterize` with the reference implementation's default separator, `-`.
    pub fn parameterize(word: &[u8]) -> Vec<u8> {
        Self::parameterize_with(word, b"-")
    }

    /// Lowercase ASCII alphanumerics, turn each space into `separator`, and
    /// **drop** every other byte.
    ///
    /// Dropping rather than substituting is the surprising part: `foo_bar`
    /// becomes `foobar` and `a-b` becomes `ab`. Only `0x20` produces a
    /// separator -- tabs and other whitespace are dropped like any other
    /// punctuation. Separator runs are never collapsed, so a doubled space
    /// yields `--`.
    pub fn parameterize_with(word: &[u8], separator: &[u8]) -> Vec<u8> {
        let mut out = Vec::with_capacity(word.len());
        for &b in word {
            if b.is_ascii_alphanumeric() {
                out.push(ascii::to_lower(b));
            } else if b == b' ' {
                out.extend_from_slice(separator);
            }
        }
        out
    }

    /// Uppercase every ASCII letter.
    pub fn upcase(word: &[u8]) -> Vec<u8> {
        ascii::upcase(word)
    }

    /// Lowercase every ASCII letter.
    pub fn downcase(word: &[u8]) -> Vec<u8> {
        ascii::downcase(word)
    }

    /// Uppercase the first byte and lowercase the rest: `cAT` -> `Cat`.
    pub fn capitalize(word: &[u8]) -> Vec<u8> {
        ascii::upper_first(&ascii::downcase(word))
    }
}

