//! Entry point: a faithful translation of `tests/test13.cpp`.
//!
//! Takes one optional positional argument and, when present, prints the results
//! of thirteen `Inflector` calls -- one per line, in the same order as the C++
//! original. With no argument it prints nothing at all, matching the C++
//! `if (argc > 1)` guard, and it always exits 0.

mod inflection;

use inflection::ascii::concat;
use inflection::Inflector;
use std::ffi::OsString;
use std::io::{self, Write};

/// Recover the raw bytes of a command-line argument.
///
/// `std::env::args()` would panic on an argument that is not valid UTF-8, and
/// lossy conversion would corrupt it. The C++ original just copies `argv[1]`
/// into a `std::string`, so on Unix we read the bytes back out verbatim to stay
/// byte-identical for inputs like `a\xffz`.
fn arg_bytes(arg: &OsString) -> Vec<u8> {
    #[cfg(unix)]
    {
        use std::os::unix::ffi::OsStrExt;
        arg.as_os_str().as_bytes().to_vec()
    }
    #[cfg(not(unix))]
    {
        arg.to_string_lossy().into_owned().into_bytes()
    }
}

fn main() {
    Inflector::initialize();

    let args: Vec<OsString> = std::env::args_os().collect();

    // C++: `if (argc > 1)`. Extra arguments past the first are ignored.
    if args.len() > 1 {
        let word = arg_bytes(&args[1]);

        let lines: [Vec<u8>; 13] = [
            Inflector::pluralize(&word),
            Inflector::singularize(&concat(&word, b"s")),
            Inflector::camelize(&concat(b"test_", &word)),
            Inflector::underscore(&concat(b"Test", &word)),
            Inflector::classify(&concat(&word, b"_table")),
            Inflector::tableize(&concat(&word, b"Class")),
            Inflector::humanize(&concat(&word, b"_id")),
            Inflector::titleize(&word),
            Inflector::dasherize(&word),
            Inflector::parameterize(&concat(&concat(b"The ", &word), b" Test")),
            Inflector::upcase(&word),
            Inflector::downcase(&word),
            Inflector::capitalize(&word),
        ];

        // Write raw bytes rather than using `println!`, so that non-UTF-8 input
        // is reproduced exactly. Write errors are ignored, as they are in the
        // C++ original, which never checks the stream state.
        let stdout = io::stdout();
        let mut out = io::BufWriter::new(stdout.lock());
        for line in &lines {
            let _ = out.write_all(line);
            let _ = out.write_all(b"\n");
        }
        let _ = out.flush();
    }
}

